const $=s=>document.querySelector(s);const presets=[{id:'cosmic',name:'Cosmic sparks',tag:'ENERGY · SPARKS',group:'energy',symbol:'✧',color:'#b6a0ff',amount:65,size:3,speed:48,spread:65,life:3},{id:'fire',name:'Campfire',tag:'NATURE · FIRE',group:'nature',symbol:'♨',color:'#ff956c',amount:95,size:7,speed:35,spread:35,life:2},{id:'magic',name:'Magic portal',tag:'ENERGY · MAGIC',group:'energy',symbol:'◎',color:'#54d8ff',amount:100,size:3,speed:25,spread:75,life:3},{id:'smoke',name:'Soft smoke',tag:'NATURE · SMOKE',group:'nature',symbol:'≋',color:'#aab4c9',amount:30,size:22,speed:20,spread:45,life:5},{id:'snow',name:'Gentle snowfall',tag:'NATURE · WEATHER',group:'nature',symbol:'❄',color:'#d0ebff',amount:65,size:3,speed:22,spread:90,life:5},{id:'ember',name:'Floating embers',tag:'NATURE · SPARKS',group:'nature',symbol:'⁙',color:'#ffc477',amount:50,size:2,speed:22,spread:65,life:4}];
let state={...presets[0],mode:'continuous',glow:true,trail:true},particles=[],playing=true,elapsed=0,last=0,spawnBudget=0,grid=true,light=false,filter='all';let savedData;try{savedData=JSON.parse(localStorage.getItem('ember-project'));if(savedData&&presets.some(p=>p.id===savedData.effect?.id)){state={...state,...savedData.effect};$('#name').value=savedData.name||'Untitled effect'}}catch{}
const definitions=[['amount','Particle amount',5,200,'A few','A lot'],['size','Particle size',1,30,'Small','Large'],['speed','Movement speed',1,100,'Drift','Rush'],['spread','Spread',5,100,'Focused','Wide'],['life','Lifetime',1,8,'Short','Long']];
function list(){const q=$('#search').value.toLowerCase();$('#presets').innerHTML=presets.filter(p=>(filter==='all'||p.group===filter)&&p.name.toLowerCase().includes(q)).map(p=>`<button class="preset ${state.id===p.id?'active':''}" data-id="${p.id}" aria-pressed="${state.id===p.id}"><span class="thumb" style="--c:${p.color}">${p.symbol}</span><span><b>${p.name}</b><small>${p.tag}</small></span><span class="arrow">${state.id===p.id?'✓':''}</span></button>`).join('')||'<p>No effects found. Try another search.</p>';document.querySelectorAll('.preset').forEach(b=>b.onclick=()=>{state={...presets.find(p=>p.id===b.dataset.id),mode:'continuous',glow:true,trail:true};restart();sync();persist()})}
function sync(){$('#effect-title').textContent=state.name+' ✦';$('#color').value=state.color;$('#mode').value=state.mode;$('#glow').checked=state.glow;$('#trail').checked=state.trail;$('#controls').innerHTML=definitions.map(([key,name,min,max,a,b])=>`<label class="control"><span class="label-row"><span>${name}</span><output id="value-${key}">${state[key]}${key==='life'?' s':''}</output></span><input type="range" min="${min}" max="${max}" value="${state[key]}" data-key="${key}" aria-label="${name}"><small><span>${a}</span><span>${b}</span></small></label>`).join('');document.querySelectorAll('[data-key]').forEach(el=>el.oninput=()=>{state[el.dataset.key]=+el.value;$('#value-'+el.dataset.key).textContent=el.value+(el.dataset.key==='life'?' s':'');persist()});document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('chosen',b.dataset.color===state.color));list()}
let saveTimer;function persist(){try{localStorage.setItem('ember-project',JSON.stringify({name:$('#name').value,effect:state}));$('#saved').textContent='All changes saved'}catch{$('#saved').textContent='Local storage unavailable'}clearTimeout(saveTimer)}function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2500)}function restart(){particles=[];elapsed=0;spawnBudget=0;if(state.mode==='burst')for(let i=0;i<state.amount*2;i++)spawn()}
$('#search').oninput=list;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));list()});document.querySelectorAll('[data-color]').forEach(b=>b.onclick=()=>{state.color=b.dataset.color;sync();persist()});$('#color').oninput=e=>{state.color=e.target.value;document.querySelectorAll('[data-color]').forEach(b=>b.classList.toggle('chosen',b.dataset.color===state.color));persist()};['mode','glow','trail'].forEach(k=>$('#'+k).onchange=e=>{state[k]=e.target.type==='checkbox'?e.target.checked:e.target.value;if(k==='mode')restart();persist()});$('#name').oninput=persist;$('#save').onclick=()=>{persist();toast('Project saved on this device')};$('#reset').onclick=()=>{state={...presets.find(p=>p.id===state.id),mode:'continuous',glow:true,trail:true};sync();restart();persist();toast('Preset restored')};$('#play').onclick=()=>{playing=!playing;$('#play').textContent=playing?'Ⅱ':'▶';$('#play').setAttribute('aria-label',playing?'Pause preview':'Play preview')};$('#restart').onclick=restart;$('#grid').onclick=()=>{grid=!grid;$('#grid').classList.toggle('selected',grid)};$('#background').onclick=()=>light=!light;
function download(blob,name){const u=URL.createObjectURL(blob);const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}function filename(){return ($('#name').value||'effect').replace(/[^a-z0-9_-]/gi,'-')}function snapshot(){canvas.toBlob(b=>{if(b)download(b,filename()+'.png')});toast('Preview image exported')}$('#snapshot').onclick=snapshot;
function dialog(html){$('#dialog-content').innerHTML=html;$('#dialog').showModal()}$('#close').onclick=()=>$('#dialog').close();$('#dialog').onclick=e=>{if(e.target===$('#dialog'))$('#dialog').close()};$('#help').onclick=()=>dialog('<div class="eyebrow">A LITTLE HELP</div><h2>From idea to effect.</h2><p><b>1. Pick a starting point.</b><br>Choose an effect on the left. Every preset is ready to play.</p><p><b>2. Make it yours.</b><br>Change the color and sliders on the right. The preview updates as you go.</p><p><b>3. Keep your creation.</b><br>Your project saves on this device. Export a JSON project or a preview image.</p><p>This is a 2D particle design tool. JSON exports are Ember projects; importing them into Unreal requires a custom Niagara integration.</p><button id="import">Import an Ember project</button>');$('#dialog-content').addEventListener('click',e=>{if(e.target.id==='import')importProject();if(e.target.id==='json'){download(new Blob([JSON.stringify({format:'ember-vfx',version:1,name:$('#name').value,effect:state},null,2)],{type:'application/json'}),filename()+'.ember.json');toast('Effect settings exported')}if(e.target.id==='png')snapshot()});$('#export').onclick=()=>dialog('<div class="eyebrow">READY TO GO</div><h2>Keep your creation.</h2><p>Export an editable Ember project, or save an image of the current preview.</p><button id="json" class="primary">↓ Effect settings (.json)</button><button id="png">↓ Preview image (.png)</button><p>Settings can be reopened in Ember from the quick guide. Unreal / Niagara export is not supported.</p>');
function importProject(){const input=document.createElement('input');input.type='file';input.accept='.json';input.onchange=async()=>{try{const data=JSON.parse(await input.files[0].text());const e=data.effect;if(data.format!=='ember-vfx'||!presets.some(p=>p.id===e?.id))throw Error();for(const[k,,min,max]of definitions)if(!Number.isFinite(e[k])||e[k]<min||e[k]>max)throw Error();if(!/^#[0-9a-f]{6}$/i.test(e.color)||!['burst','continuous'].includes(e.mode))throw Error();state={...presets.find(p=>p.id===e.id),...Object.fromEntries(['color','amount','size','speed','spread','life','mode','glow','trail'].map(k=>[k,e[k]]))};$('#name').value=String(data.name||'Imported effect').slice(0,100);sync();restart();persist();$('#dialog').close();toast('Project imported')}catch{toast('That file is not a valid Ember project')}};input.click()}
const canvas=$('#canvas'),ctx=canvas.getContext('2d');let w=600,h=600;const resize=new ResizeObserver(()=>{const r=canvas.parentElement.getBoundingClientRect();w=r.width;h=r.height;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;ctx.setTransform(devicePixelRatio,0,0,devicePixelRatio,0,0)});resize.observe(canvas.parentElement);
function spawn(){const angle=Math.random()*Math.PI*2,spread=state.spread/100;let x=w/2+(Math.random()-.5)*spread*70,y=h*.64;let vx=Math.cos(angle)*state.speed*spread*2,vy=-Math.random()*state.speed*2-15;if(state.id==='magic'){x=w/2+Math.cos(angle)*spread*125;y=h*.48+Math.sin(angle)*spread*125;vx=Math.cos(angle)*state.speed*.5;vy=Math.sin(angle)*state.speed*.5}if(state.id==='snow'){x=Math.random()*w;y=-10;vx=(Math.random()-.5)*state.speed;vy=state.speed*2}if(state.id==='cosmic'){vx=Math.cos(angle)*state.speed*spread*2;vy=Math.sin(angle)*state.speed*spread*2-25}particles.push({x,y,vx,vy,age:0,life:state.life*(.5+Math.random()*.5),size:state.size*(.4+Math.random()*.8),seed:Math.random()*6})}
function frame(now){const dt=Math.min((now-last)/1000,.04)*(+$('#speed').value);last=now;if(playing){elapsed+=dt;if(state.mode==='continuous'){spawnBudget+=dt*state.amount;while(spawnBudget>=1){spawn();spawnBudget--}}else if(elapsed>state.life+.5){restart()}particles.forEach(p=>{p.age+=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;if(state.id==='fire'||state.id==='smoke'||state.id==='ember')p.vx+=Math.sin(p.age*3+p.seed)*dt*12});particles=particles.filter(p=>p.age<p.life)}ctx.globalCompositeOperation='source-over';ctx.fillStyle=light?'#272730':'#101015';ctx.fillRect(0,0,w,h);const gradient=ctx.createRadialGradient(w/2,h*.5,0,w/2,h*.5,w*.5);gradient.addColorStop(0,light?'#35303e':'#21192f');gradient.addColorStop(1,'transparent');ctx.fillStyle=gradient;ctx.fillRect(0,0,w,h);if(grid){ctx.strokeStyle=light?'#45414d':'#282332';ctx.lineWidth=.6;for(let i=-10;i<=10;i++){ctx.beginPath();ctx.moveTo(w/2+i*20,h*.66);ctx.lineTo(w/2+i*100,h);ctx.stroke()}for(let i=0;i<9;i++){const y=h*.66+(i/8)**2*h*.34;ctx.beginPath();ctx.moveTo(0,y);ctx.lineTo(w,y);ctx.stroke()}ctx.strokeStyle='#40334e';ctx.beginPath();ctx.ellipse(w/2,h*.67,65,15,0,0,Math.PI*2);ctx.stroke()}
ctx.globalCompositeOperation=state.id==='smoke'?'source-over':'lighter';particles.forEach(p=>{const fade=Math.sin(Math.PI*Math.min(p.age/p.life,1));const s=p.size*(state.id==='smoke'?1+p.age*.65:1);ctx.globalAlpha=fade*(state.id==='smoke'?.16:.85);ctx.fillStyle=state.color;ctx.shadowColor=state.color;ctx.shadowBlur=state.glow?s*5:0;if(state.trail&&state.id!=='smoke'){ctx.strokeStyle=state.color;ctx.lineWidth=Math.max(s*.45,.5);ctx.beginPath();ctx.moveTo(p.x,p.y);ctx.lineTo(p.x-p.vx*.07,p.y-p.vy*.07);ctx.stroke()}ctx.beginPath();ctx.arc(p.x,p.y,s,0,Math.PI*2);ctx.fill()});ctx.globalAlpha=1;ctx.shadowBlur=0;ctx.globalCompositeOperation='source-over';$('#particle-count').textContent=particles.length+' particles';$('#time').textContent=(elapsed%10).toFixed(2)+' s';$('.timeline div').style.width=(elapsed%10)*10+'%';requestAnimationFrame(frame)}sync();requestAnimationFrame(frame);
